java.util.Map<java.awt.RenderingHints.Key, Object> hints = new java.util.HashMap<>();
hints.put(java.awt.RenderingHints.KEY_INTERPOLATION, java.awt.RenderingHints.VALUE_INTERPOLATION_BICUBIC);
hints.put(java.awt.RenderingHints.KEY_ANTIALIASING, java.awt.RenderingHints.VALUE_ANTIALIAS_ON);

net.coobird.thumbnailator.resizers.BicubicResizer resizer = new net.coobird.thumbnailator.resizers.BicubicResizer(hints);

int targetWidth = Math.max(1, sourceImage.getWidth() / 2);
int targetHeight = Math.max(1, sourceImage.getHeight() / 2);
int type = sourceImage.getType() == java.awt.image.BufferedImage.TYPE_CUSTOM 
    ? java.awt.image.BufferedImage.TYPE_INT_ARGB 
    : sourceImage.getType();

java.awt.image.BufferedImage dest = new java.awt.image.BufferedImage(targetWidth, targetHeight, type);

resizer.resize(sourceImage, dest);

assert dest.getWidth() == targetWidth : "Destination width mismatch";
assert dest.getHeight() == targetHeight : "Destination height mismatch";

System.out.println("__CHECK__ BicubicResizer " + dest.getWidth() + "x" + dest.getHeight());
